const TOOLS = [
  {
    name: 'format_value',
    description: 'Format a value as text or integer.',
    inputSchema: {
      type: 'object',
      properties: {
        value: { type: 'string' },
        kind: { type: 'string', enum: ['text', 'integer'] }
      },
      required: ['value', 'kind'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  if (name !== 'format_value') {
    throw new Error('Unknown tool: ' + name);
  }
  const schema = TOOLS[0].inputSchema;
  // validate
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const keys = Object.keys(args);
  // extra fields
  for (const k of keys) {
    if (!(k in schema.properties)) {
      throw new Error('Unknown field: ' + k);
    }
  }
  // required
  for (const r of schema.required) {
    if (!(r in args)) {
      throw new Error('Missing required field: ' + r);
    }
  }
  // value type
  if (typeof args.value !== 'string') {
    throw new Error('value must be a string');
  }
  // kind enum
  if (!schema.properties.kind.enum.includes(args.kind)) {
    throw new Error('kind must be one of text, integer');
  }
  // execute
  let text;
  if (args.kind === 'text') {
    text = args.value.toUpperCase();
  } else { // integer
    const n = Number.parseInt(args.value, 10);
    if (!Number.isInteger(n) || !/^\s*[+-]?\d+\s*$/.test(args.value)) {
      throw new Error('Malformed integer: ' + args.value);
    }
    text = String(n);
  }
  return { content: [{ type: 'text', text }] };
}
